SourceCode.Declaration:
/// <summary>
/// Count control center: Hold and Release (menu item parameter HOLD or RELEASE). A held store
/// journal is skipped by the nightly posting until it is released.
/// </summary>
class HSMobileOpsCountStoreJournalHold
{
}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsCountStoreJournal storeJournal = _args ? _args.record() : null;

    if (!storeJournal || !storeJournal.RecId)
    {
        throw error('Select a store first.');
    }
    HSMobileOpsCountStoreJournalEngine::hold(storeJournal.RecId, _args.parm() != 'RELEASE');
    HSMobileOpsCountRefresh::researchCaller(_args);
}
